\documentclass{article}
\title{Faithful Abstractive Summarization with Entailment Feedback}
\author{Anon}
\begin{document}
\maketitle
\begin{abstract}
We improve the factual consistency of abstractive summarization with an entailment-feedback training signal.
\end{abstract}
\section{Introduction}
Abstractive summarizers sometimes hallucinate content that contradicts the source document. We use an entailment model to score candidate summaries and feed the score back into training.
\section{Experiments}
Our method reduces factual errors by 30 percent relative on two benchmarks.
\end{document}
